  Object.assign(PRESETS, GAME_PATRIOTIC_PRESETS);

  // Evergreen botanical / giftable style presets — added Sep 2026.
  const EVERGREEN_PRESETS = {};
  const makeFloralPreset = (styleName, northStar, palette, illustrationMode, lineQuality, fills, realism, detailLevel, composition, motifs, textures, distress, extraDo = [], extraDont = []) => ({
    styleName,
    description: northStar,
    northStar,
    audience: 'People drawn to botanical illustration, personalized floral art, birth flowers, elegant decorative design, and timeless evergreen aesthetics.',
    emotional: ['elegant', 'polished', 'personal'],
    avoid: ['Christmas theming', 'generic POD clipart', 'mockup presentation'],
    palette,
    displayLettering: 'Elegant highly legible personalization lettering. Favor refined serif, clean small caps, or restrained script for a short name or monogram only. Text must remain secondary to the botanical artwork.',
    supportingLettering: 'Small refined serif or clean sans; minimal supporting text only.',
    illustrationMode,
    lineQuality,
    fills,
    realism,
    detailLevel,
    subjectTreatment: 'Make the requested birth flower, botanical subject, name, initial, monogram, or niche the hero. The searched subject determines the flowers and imagery; do not substitute unrelated botanicals.',
    composition,
    hierarchy: 'birth flower or hero motif first, personalization second, ornamental details third',
    whitespace: 'Use intentional breathing room and readable negative space where the composition calls for it. Let botanical elements crop naturally at the outer edges when appropriate to the selected style.',
    symmetry: 'balanced but naturally organic',
    shapeLanguage: ['tall botanical stems', 'flowing organic curves', 'edge-cropped florals', 'layered botanical forms'],
    motifs,
    textures,
    distress,
    doRules: [
      'Let the selected visual style control the artwork rather than depicting an object that might display it.',
      'When the search is a birth month or birth flower, use the correct requested flower as the botanical hero; never substitute culinary herbs or unrelated plants.',
      'Generate no wording unless the search explicitly requests text or personalization.',
      'When personalization is requested, include only the requested name, initial, date, month, or wording.',
      'Adapt the actual flower, subject, and niche to the search term.',
      'Keep the botanical subject recognizable and visually dominant.',
      ...extraDo
    ],
    dontRules: [
      'No Christmas trees, ornaments, Santa, snowflakes, candy canes, or other Christmas theming unless explicitly requested.',
      'Do not depict merchandise, electronics, containers, templates, mockups, packaging, hands, staged scenes, or presentation objects unless explicitly requested by the search.',
      'No automatically generated titles, captions, labels, slogans, marketing copy, specimen text, or descriptive wording.',
      'No basil, thyme, rosemary, culinary herb collections, or herb-garden themes unless explicitly requested.',
      'No plaques, title cards, banners, framed labels, information panels, or decorative text boxes unless explicitly requested.',
      'No fake metallic foil, glitter, rhinestones, or photoreal craft materials unless the selected style explicitly calls for a graphic simulation.',
      'No tiny unreadable decorative text.',
      ...extraDont
    ]
  });

