    document.querySelector('#ldd-scout-app .ldd-count').textContent=`${items.length} of ${allPresets().length} styles`;
    grid.innerHTML=items.length?items.map(p=>{const desc=p.description||p.northStar||p.audience||'';const sw=(p.palette||[]).slice(0,5).map(c=>`<i class="ldd-swatch" style="background:${esc(c.hex)}" title="${esc(c.name||c.hex)}"></i>`).join('');return `<article class="ldd-card"><div class="ldd-card-top"><div><h3>${esc(p.styleName)}</h3><p>${esc(desc)}</p></div><span class="ldd-chip">${esc(categoryLabel(categoryFor(p.key)))}</span></div><div class="ldd-card-bottom"><div class="ldd-swatches">${sw}</div><div class="ldd-actions">${(p.key.startsWith('custom_')||p.key.startsWith('imported_'))?`<button class="ldd-icon" data-edit="${p.key}">Edit</button>`:''}<button class="ldd-icon" data-move="${p.key}">Move / Add</button><button class="ldd-icon" data-delete="${p.key}">Delete</button><button class="ldd-fill" data-fill="${p.key}">Auto Fill</button></div></div></article>`}).join(''):`<div class="ldd-empty">No styles match.</div>`;
    grid.querySelectorAll('[data-fill]').forEach(b=>b.onclick=async()=>{b.disabled=true;const old=b.textContent;b.textContent='Filling…';try{const p=mergedPresets()[b.dataset.fill];if(p){PRESETS.__temp=p;const ok=await fillPreset('__temp');delete PRESETS.__temp;if(ok)closeApp()}}finally{b.disabled=false;b.textContent=old}});
    grid.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deletePreset(b.dataset.delete));
