  function moveAddCategory(key){const src=mergedPresets()[key];if(!src)return;const options=[...CATEGORY_MAP.map(c=>({id:c.id,label:c.label})),...userCategories];const current=styleCategories({key,...src});const msg='Choose category number. Prefix with + to ADD while keeping existing categories. Enter just the number to MOVE into that category.\n\n'+options.map((c,i)=>`${i+1}. ${c.label}${current.includes(c.id)?' ✓':''}`).join('\n');const ans=prompt(msg);if(!ans)return;const add=ans.trim().startsWith('+');const n=parseInt(ans.replace('+','').trim(),10)-1;if(!options[n])return alert('Invalid category.');const target=options[n].id;const p={...src};p.categories=add?[...new Set([...(p.categories||[]),target])]:[target];if(!(key.startsWith('custom_')||key.startsWith('imported_'))){customPresets[key]={...p,_override:true}}else customPresets[key]=p;saveLibrary();renderNav();renderCards();toast(`${p.styleName} ${add?'added to':'moved to'} ${options[n].label}.`)}
