    const items=allPresets();
    const list=wrap.querySelector('.ldd-share-list');
    list.innerHTML=items.map(p=>`<label class="ldd-share-item"><input type="checkbox" class="ldd-share-check" data-key="${esc(p.key)}"><span class="ldd-share-info"><strong>${esc(p.styleName||p.key)}</strong><small>${esc(styleCategories(p).map(categoryLabel).join(' • '))}</small><span class="ldd-share-palette">${(p.palette||[]).slice(0,8).map(c=>`<i style="background:${esc(c.hex||c)}"></i>`).join('')}</span></span></label>`).join('');
    wrap.querySelector('.ldd-share-search').value='';
